const fs = require("fs");
const zlib = require("zlib");
const token = fs.readFileSync("/tmp/owner_at", "utf8").trim();
const baseUrl = "https://api.ivxholding.com";

function commitFile(path, message) {
  const content = fs.readFileSync(path, "utf8");
  const gz = zlib.gzipSync(Buffer.from(content, "utf8"));
  const b64 = gz.toString("base64");
  const payload = {
    action: "github_commit_file",
    input: { path, content: b64, contentEncoding: "gzip-base64", message },
    confirm: true,
    confirmText: "CONFIRM_IVX_GITHUB_WRITE"
  };
  const tmp = `/tmp/commit_${path.replace(/[^a-z0-9]/g, "_")}.json`;
  fs.writeFileSync(tmp, JSON.stringify(payload));
  const cmd = `curl -s -X POST "${baseUrl}/api/ivx/developer-deploy/action" -H "Authorization: Bearer ${token}" -H "Content-Type: application/json" --data-binary "@${tmp}"`;
  console.log(`\n--- Committing ${path} ---`);
  const result = require("child_process").execSync(cmd, { encoding: "utf8", timeout: 30000 });
  console.log(result);
  const parsed = JSON.parse(result);
  if (!parsed.ok) {
    console.error(`FAILED: ${parsed.error || JSON.stringify(parsed)}`);
    process.exit(1);
  }
  return parsed;
}

